5. **C Program to Check Whether a Number is Prime or Not**:
   ```c
   #include <stdio.h>

   int main() {
       int num, i, isPrime = 1;
       printf("Enter a positive integer: ");
       scanf("%d", &num);

       for (i = 2; i <= num / 2; ++i) {
           if (num % i == 0) {
               isPrime = 0;
               break;
           }
       }

       if (isPrime && num > 1)
           printf("%d is a prime number.\n", num);
       else
           printf("%d is not a prime number.\n", num);

       return 0;
   }
   ```

